export function renderDemoTestUsersMarkdown() {
  const lines = [
    "# Yenomi ID — Demo test kullanıcıları",
    "",
    "Bu dosya elle tutulmaz. Kaynak `tests/fixtures/demo-user-matrix.ts` / `.mjs`.",
    "Yenilemek için: `npm run docs:demo-users`.",
    "`scripts/seed-demo-scenarios.mjs` aynı kaydı import eder.",
    "",
    "Şifre git’e yazılmaz. Local apply için `.env.local` içinde `DEMO_SEED_PASSWORD` ve `ALLOW_LOCAL_DEMO_SEED=true`.",
    "Temiz kurulumda `--reset-demo`, tüm `@yenomi.test` hesaplarını, `TEST` kimlik katmanını ve bunlara bağlı demo verisini silip bu matrisi yeniden kurar; gerçek kullanıcı veya katalog verisine dokunmaz.",
    "Production’da `@yenomi.test` hesabı olamaz (`verify:production:no-demo-users`).",
    "",
    "## Giriş yapılabilen hesaplar",
    "",
    "| Anahtar | E-posta | Tür | Portal | Şirket / Rol | Profil | Kart | QA niyeti |",
    "|---|---|---|---|---|---|---|---|",
  ];
  for (const user of DEMO_LOGIN_USERS) {
    const orgInfo = user.organizationSlug ? `${user.organizationSlug} (${user.role || "-"})` : "-";
    const profileInfo = user.profile ? `\`${user.profile.slug}\`` : user.profile === null ? "Yok" : "-";
    const cardInfo = user.cards?.length ? user.cards.map((c) => `\`${c.code}\` (${c.status})`).join(", ") : "-";
    lines.push(
      `| \`${user.key}\` | \`${user.email}\` | ${user.kind} | ${user.loginScope} | ${orgInfo} | ${profileInfo} | ${cardInfo} | ${user.intent} |`
    );
  }
  lines.push(
    "",
    "## Misafir siparişleri (Auth yok)",
    "",
    "Aktivasyon URL’si yalnız `seed:e2e` çıktısında bir kez basılır; token git’e yazılmaz.",
    "",
    "| E-posta | Tür | Sipariş | SKU | QA niyeti |",
    "|---|---|---|---|---|",
  );
  for (const guest of DEMO_GUEST_ORDERS) {
    lines.push(`| \`${guest.email}\` | ${guest.kind} | \`${guest.orderNumber}\` | \`${guest.variantSku}\` | ${guest.intent} |`);
  }
  lines.push(
    "",
    "## Davet fixture’ları (Auth yok)",
    "",
    "| E-posta | Tür | Şirket | Rol | Durum | QA niyeti |",
    "|---|---|---|---|---|---|",
  );
  for (const invite of DEMO_INVITE_FIXTURES) {
    lines.push(
      `| \`${invite.email}\` | ${invite.kind} | \`${invite.organizationSlug}\` | ${invite.role} | ${invite.status} | ${invite.intent} |`
    );
  }
  lines.push(
    "",
    "## Kapasite senaryoları",
    "",
    "| Şirket | Plan | Koltuk |",
    "|---|---|---|",
  );
  for (const scenario of DEMO_CORPORATE_CAPACITY_SCENARIOS) {
    lines.push(`| ${scenario.name} | ${scenario.plan} | ${scenario.used}/${scenario.limit} |`);
  }
  lines.push(
    "",
    "## Kimlik çarpışması",
    "",
    `\`${DEMO_IDENTITY_COLLISION.emailPrefix}*\` adresleri görünen adı \`${DEMO_IDENTITY_COLLISION.displayName}\` olan ayrı üyelerdir. ${DEMO_IDENTITY_COLLISION.intent}`,
    "",
    "## Apply",
    "",
    "```bash",
    "ALLOW_LOCAL_DEMO_SEED=true DEMO_SEED_PASSWORD='…' npm run seed:demo -- --apply --reset-demo --allow-non-empty",
    "```",
    "",
  );
  return `${lines.join("\n")}\n`;
}
